import{_ as l,C as e,c as i,o as s,j as o,G as a,ak as c,a as p}from"./chunks/framework.D7ejh1zC.js";const f=JSON.parse('{"title":"前言","description":"","frontmatter":{},"headers":[],"relativePath":"ai/第二章 AI Agent 工程基础/前言.md","filePath":"practice/ai/AI Agent+智能大屏设计器/第二章 AI Agent 工程基础/前言.md","lastUpdated":1787062422000}'),h={name:"ai/第二章 AI Agent 工程基础/前言.md"};function _(A,t,b,g,u,m){const n=e("mdInfo"),r=e("NolebaseGitContributors"),d=e("NolebaseGitChangelog");return s(),i("div",null,[t[0]||(t[0]=o("h1",{id:"前言",tabindex:"-1"},[p("前言 "),o("a",{class:"header-anchor",href:"#前言","aria-label":'Permalink to "前言"'},"​")],-1)),a(n),t[1]||(t[1]=c('<h2 id="为什么要学习-ai-agent" tabindex="-1">为什么要学习 AI Agent <a class="header-anchor" href="#为什么要学习-ai-agent" aria-label="Permalink to &quot;为什么要学习 AI Agent&quot;">​</a></h2><p>AI 从“能回答”到“能做事”，这是一个重要的突破。</p><p>以前更多的是<strong>问AI</strong>，输入问题得到回到、文案或片段代码。未来更多的是<strong>交给AI</strong>，理解目标、调用工具、完成任务。</p><p>核心变化：AI不止输出文本，而是参与任务流程。</p><p>让 AI 真正做事的关键方式：</p><ul><li>LLM大模型：负责理解、推理和决策</li><li>工具：连接系统、数据和能力</li><li>控制流程：一步步观察结果并继续行动</li><li>目标/状态管理：记录目标、上下文和当前进展</li></ul><blockquote><p>Agent = LLM + 工具+ 流程控制 + 目标/状态管理</p></blockquote><h2 id="传统大模型-vs-agent" tabindex="-1">传统大模型 vs Agent <a class="header-anchor" href="#传统大模型-vs-agent" aria-label="Permalink to &quot;传统大模型 vs Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对吧维度</th><th>传统大模型</th><th>Agent</th></tr></thead><tbody><tr><td>角色定位</td><td>会思考和表达的大脑</td><td>带工具的执行者</td></tr><tr><td>主要产出</td><td>回答、文本、建议</td><td>动作、结果、过程反馈</td></tr><tr><td>能力边界</td><td>主要停在生成内容</td><td>能连接外部系统</td></tr><tr><td>典型动作</td><td>你问，它答</td><td>它做，观察，再继续</td></tr></tbody></table><blockquote><p>差异不在“更聪明”，而在“能不能进入任务执行”</p></blockquote><h2 id="为什么现在要学" tabindex="-1">为什么现在要学 <a class="header-anchor" href="#为什么现在要学" aria-label="Permalink to &quot;为什么现在要学&quot;">​</a></h2><p>因为市场需要。</p><ul><li>产品趋势：越来越多AI产品不再只是聊天工具，开始帮助用户完成真实任务</li><li>企业需求：企业需要AI能连接工具、数据和业务流程</li><li>岗位变化：越来越多岗位需要理解大模型、工具调用和流程编排能力</li></ul>',13)),a(r),a(d)])}const k=l(h,[["render",_]]);export{f as __pageData,k as default};
